  // ============ Validation ============
  public static void validateX509Cert(X509.X509Cert msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate base64 (assert_base64)
    if (!msg.getBase64().isEmpty()) {
      Validation.validateBase64(msg.getBase64(), "base64");
    }
    // Validate base64 (assert_required)
    if (msg.getBase64().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field base64 is required");
    }
  }

  public static void validateX509CertRequest(X509.X509CertRequest msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate exp (assert_duration: POSITIVE)
    if (msg.getExp() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field exp must be positive (> 0), got: %d", msg.getExp()));
    }
    // Validate issuer (assert_required)
    if (msg.getIssuer().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field issuer is required");
    }
    // Validate issuer (assert_min_length: 1)
    if (msg.getIssuer().length() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field issuer must be at least 1 characters, got: %d", msg.getIssuer().length()));
    }
  }

  public static void validateX509CertChain(X509.X509CertChain msg) throws ProtoException {
    if (msg == null) {
      return;
    }
  }

  // ============ Merge ============
  public static X509.X509Cert.Builder mergeX509Cert(X509.X509Cert dst, X509.X509Cert src) {
    X509.X509Cert.Builder builder = dst.toBuilder();
    if (dst.getId().isEmpty()) {
      builder.setId(src.getId());
    }
    if (dst.getBase64().isEmpty()) {
      builder.setBase64(src.getBase64());
    }
    return builder;
  }

  public static X509.X509CertRequest.Builder mergeX509CertRequest(
      X509.X509CertRequest dst, X509.X509CertRequest src) {
    X509.X509CertRequest.Builder builder = dst.toBuilder();
    if (!dst.hasKey() && src.hasKey()) {
      builder.setKey(src.getKey());
    }
    if (dst.getExp() == 0) {
      builder.setExp(src.getExp());
    }
    if (!dst.hasMetadata() && src.hasMetadata()) {
      builder.setMetadata(src.getMetadata());
    }
    if (dst.getKeyUsageValue() == 0) {
      builder.setKeyUsageValue(src.getKeyUsageValue());
    }
    if (dst.getExtKeyUsageList().isEmpty()) {
      builder.addAllExtKeyUsage(src.getExtKeyUsageList());
    }
    if (dst.getIssuer().isEmpty()) {
      builder.setIssuer(src.getIssuer());
    }
    if (!dst.getIsCa()) {
      builder.setIsCa(src.getIsCa());
    }
    if (dst.getPathLenConstraint() == 0) {
      builder.setPathLenConstraint(src.getPathLenConstraint());
    }
    if (dst.getDnsNamesList().isEmpty()) {
      builder.addAllDnsNames(src.getDnsNamesList());
    }
    if (dst.getUriSansList().isEmpty()) {
      builder.addAllUriSans(src.getUriSansList());
    }
    return builder;
  }

  public static X509.X509CertChain.Builder mergeX509CertChain(
      X509.X509CertChain dst, X509.X509CertChain src) {
    X509.X509CertChain.Builder builder = dst.toBuilder();
    if (dst.getChainList().isEmpty()) {
      builder.addAllChain(src.getChainList());
    }
    if (!dst.hasKey() && src.hasKey()) {
      builder.setKey(src.getKey());
    }
    return builder;
  }

