  public static Map<String, String> x509CertRequestToEnvVar(X509.X509CertRequest msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasKey()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.key.Helpers
              .publicKeyToEnvVar(msg.getKey()));
    }
    result.put("PROTO_X509_CERT_REQUEST_EXP", String.valueOf(msg.getExp()));
    result.put("PROTO_X509_CERT_REQUEST_KEY_USAGE", x509KeyUsageToString(msg.getKeyUsage()));
    if (!msg.getExtKeyUsageList().isEmpty()) {
      result.put(
          "PROTO_X509_CERT_REQUEST_EXT_KEY_USAGE",
          msg.getExtKeyUsageList().stream()
              .map(v -> x509ExtKeyUsageToString(v))
              .collect(Collectors.joining(",")));
    }
    result.put("PROTO_X509_CERT_REQUEST_ISSUER", msg.getIssuer());
    result.put("PROTO_X509_CERT_REQUEST_IS_CA", String.valueOf(msg.getIsCa()));
    result.put(
        "PROTO_X509_CERT_REQUEST_PATH_LEN_CONSTRAINT", String.valueOf(msg.getPathLenConstraint()));
    if (!msg.getDnsNamesList().isEmpty()) {
      result.put("PROTO_X509_CERT_REQUEST_DNS_NAMES", String.join(",", msg.getDnsNamesList()));
    }
    if (!msg.getUriSansList().isEmpty()) {
      result.put("PROTO_X509_CERT_REQUEST_URI_SANS", String.join(",", msg.getUriSansList()));
    }
    return result;
  }

  public static X509.X509CertRequest.Builder x509CertRequestFromEnvVar(Map<String, String> env) {
    X509.X509CertRequest.Builder builder = X509.X509CertRequest.newBuilder();
    String val;
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.key.Helpers
              .publicKeyFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setKey(sub);
      }
    }
    val = env.get("PROTO_X509_CERT_REQUEST_EXP");
    if (val != null && !val.isEmpty()) {
      builder.setExp(Long.parseLong(val));
    }
    val = env.get("PROTO_X509_CERT_REQUEST_KEY_USAGE");
    if (val != null && !val.isEmpty()) {
      builder.setKeyUsage(parseX509KeyUsage(val));
    }
    val = env.get("PROTO_X509_CERT_REQUEST_EXT_KEY_USAGE");
    if (val != null && !val.isEmpty()) {
      for (String part : val.split(",")) {
        builder.addAllExtKeyUsage(
            java.util.Collections.singletonList(parseX509ExtKeyUsage(part.trim())));
      }
    }
    val = env.get("PROTO_X509_CERT_REQUEST_ISSUER");
    if (val != null && !val.isEmpty()) {
      builder.setIssuer(val);
    }
    val = env.get("PROTO_X509_CERT_REQUEST_IS_CA");
    if (val != null && !val.isEmpty()) {
      builder.setIsCa(Boolean.parseBoolean(val));
    }
    val = env.get("PROTO_X509_CERT_REQUEST_PATH_LEN_CONSTRAINT");
    if (val != null && !val.isEmpty()) {
      builder.setPathLenConstraint(Integer.parseInt(val));
    }
    val = env.get("PROTO_X509_CERT_REQUEST_DNS_NAMES");
    if (val != null && !val.isEmpty()) {
      builder.addAllDnsNames(Arrays.asList(val.split(",")));
    }
    val = env.get("PROTO_X509_CERT_REQUEST_URI_SANS");
    if (val != null && !val.isEmpty()) {
      builder.addAllUriSans(Arrays.asList(val.split(",")));
    }
    return builder;
  }

  public static Map<String, String> x509CertChainToEnvVar(X509.X509CertChain msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasKey()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.key.Helpers
              .keyToEnvVar(msg.getKey()));
    }
    return result;
  }

